from plotly.subplots import make_subplots
import plotly.graph_objects as go
def chart(d,s):
 f=make_subplots(rows=4,cols=1,shared_xaxes=True,vertical_spacing=.025,row_heights=[.57,.13,.15,.15]); f.add_trace(go.Candlestick(x=d.Date,open=d.Open,high=d.High,low=d.Low,close=d.Close,increasing_line_color="#70f2e5",decreasing_line_color="#ff6f91",name="XAU/USD"),row=1,col=1); f.add_trace(go.Scatter(x=d.Date,y=d.EMA20,name="EMA20",line={"color":"#4bdcff"}),row=1,col=1); f.add_trace(go.Scatter(x=d.Date,y=d.EMA50,name="EMA50",line={"color":"#af91ff"}),row=1,col=1); f.add_trace(go.Bar(x=d.Date,y=d.Volume,name="Volume",marker_color="#3ad5b766"),row=2,col=1); f.add_trace(go.Scatter(x=d.Date,y=d.RSI,name="RSI14",line={"color":"#c6a7ff"}),row=3,col=1); f.add_hline(y=70,line_dash="dot",row=3,col=1); f.add_hline(y=30,line_dash="dot",row=3,col=1); hist=d.MACD-d.SIGNAL; f.add_trace(go.Bar(x=d.Date,y=hist,name="MACD Hist",marker_color=["#48d9be" if v>=0 else "#ff687f" for v in hist]),row=4,col=1); f.add_trace(go.Scatter(x=d.Date,y=d.MACD,name="MACD",line={"color":"#55dcff"}),row=4,col=1); f.add_trace(go.Scatter(x=d.Date,y=d.SIGNAL,name="Signal",line={"color":"#ff9f7a"}),row=4,col=1)
 for y,t,c in [(s["entry"],"ENTRY reference","#55dfff"),(s["sl"],"SL reference","#ff4f72"),(s["tp"],"TP reference","#45e0ac")]:f.add_hline(y=y,line_color=c,line_width=2,annotation_text=f"{t}: {y:.2f}",annotation_bgcolor=c,row=1,col=1)
 f.update_layout(height=770,template="plotly_dark",paper_bgcolor="rgba(0,0,0,0)",plot_bgcolor="#061625",margin=dict(l=10,r=55,t=35,b=20),xaxis_rangeslider_visible=False,hovermode="x unified",legend=dict(orientation="h",y=1.03)); f.update_xaxes(gridcolor="#31506a55"); f.update_yaxes(gridcolor="#31506a55",side="right"); f.update_yaxes(range=[0,100],row=3,col=1); return f
